CREATE OR REPLACE VIEW core.customer AS SELECT customer_id,NULLIF(btrim(customer_name),'') customer_name,core.clean_phone(phone_number) phone_number,NULLIF(initcap(lower(gender)),'') gender,NULLIF(initcap(lower(marital_status)),'') marital_status,core.try_numeric(income) income,NULLIF(income_band,'') income_band,NULLIF(occupation,'') occupation,NULLIF(occupation_risk,'') occupation_risk,core.try_numeric(age_at_entry)::int age_at_entry,NULLIF(preferred_language,'') preferred_language,region_id FROM landing.dim_customer;
CREATE OR REPLACE VIEW core.policy AS SELECT policy_id,customer_id,policy_type_code,region_id,current_agent_id,NULLIF(nominee_name,'') nominee_name,core.try_numeric(sum_assured) sum_assured,core.try_numeric(premium_amount) premium_amount,core.try_date(policy_start_date) policy_start_date,core.try_date(date_of_purchase) purchase_date,core.try_date(policy_end_date) policy_end_date,core.try_date(date_of_maturity) maturity_date,NULLIF(status,'') status,core.try_date(last_paid_date) last_paid_date,core.try_numeric(payment_gap_months)::int payment_gap_months,core.try_numeric(total_premium_paid) total_premium_paid,core.try_numeric(total_premium_payable) total_premium_payable,core.normalize_yes_no(fraud_risk_flag) fraud_risk_flag FROM landing.fact_policy;
CREATE OR REPLACE VIEW core.agent AS SELECT agent_id,NULLIF(name,'') agent_name,core.try_numeric(experience_years)::int experience_years,core.try_date(joining_date) joining_date,region_id,core.try_numeric(performance_rating) performance_rating,NULLIF(languages_known,'') languages_known,NULLIF(specialisation,'') specialisation,core.try_numeric(product_wise_conversion_rate) conversion_rate,core.try_numeric(median_ticket_size) median_ticket_size,core.try_numeric(sales_cycle_efficiency) sales_cycle_efficiency,core.try_numeric(drop_off_rate_after_first_call) first_call_dropoff_rate,core.try_numeric(upsell_conversion_percentage) upsell_rate,core.try_numeric(sla_adherence) sla_adherence FROM landing.dim_agent;
CREATE OR REPLACE VIEW core.region AS SELECT region_id,region_name,state,zone,region_type,region_dir FROM landing.dim_region;
CREATE OR REPLACE VIEW core.lead AS SELECT lead_id,customer_id,campaign,campaign_type,NULLIF(utm_link,'') utm_link,core.try_numeric(time_spent_on_pricing_page) pricing_page_time,core.try_numeric(scroll_depth) scroll_depth,core.try_numeric(page_visits_count)::int page_visits,core.try_numeric(engagement_score) engagement_score,core.normalize_yes_no(downloaded_brochure) downloaded_brochure,core.normalize_yes_no(used_maturity_calculator) used_maturity_calculator,core.normalize_yes_no(compared_plans) compared_plans,lead_stage,lead_status,core.try_date(lead_status_date) lead_status_date,rejection_reason,core.normalize_yes_no(follow_up_required) follow_up_required,core.try_date(follow_up_date) follow_up_date,follow_up_pitch,core.normalize_yes_no(proposal_form_completed) proposal_form_completed,competitor,authority,budget,need,timeline,prospect_needs,prospect_needs_addressed FROM landing.fact_lead_funnel;
CREATE OR REPLACE VIEW core.underwriting AS SELECT underwriting_id,customer_id,core.try_numeric(bmi_value) bmi,core.normalize_yes_no(smoking_flag) smoking_flag,core.normalize_yes_no(alcohol_flag) alcohol_flag,blood_pressure_category,sugar_risk_category,cholesterol_risk_category,ecg_risk_category,preexisting_condition_identified,preexisting_condition_type,core.try_numeric(waiting_period_months)::int waiting_period_months,core.normalize_yes_no(long_term_medication) long_term_medication,core.try_numeric(prescription_frequency_monthly)::int prescription_frequency_monthly,core.try_numeric(aggregated_medical_risk_score) medical_risk_score,risk_score_category,core.try_numeric(base_premium) base_premium FROM landing.fact_underwriting;
CREATE OR REPLACE VIEW core.rider AS SELECT rider_record_id,policy_id,customer_id,rider_type_id,core.try_numeric(rider_premium) rider_premium,core.try_numeric(rider_sum_assured) rider_sum_assured,core.try_date(rider_start_date) rider_start_date,core.try_date(rider_end_date) rider_end_date,rider_status FROM landing.fact_rider;
